CREATE TRIGGER growth_feedback_update INSTEAD OF UPDATE ON growth_feedback BEGIN
 SELECT CASE WHEN OLD.status='confirmed' THEN RAISE(ABORT,'growth_feedback_immutable') END;
 UPDATE lesson_submissions SET personal_json=(SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')=OLD.id THEN json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at) ELSE value END)) FROM json_each(personal_json)) WHERE tenant_id=OLD.tenant_id AND id=OLD.submission_id;
 UPDATE lesson_comments SET feedback_versions_json=(SELECT json_group_array(json(CASE WHEN json_extract(value,'$.id')=OLD.id THEN json_object('id',NEW.id,'lesson_id',NEW.lesson_id,'submission_id',NEW.submission_id,'student_id',NEW.student_id,'seq',NEW.seq,'doc_json',NEW.doc_json,'status',NEW.status,'confirmed_at',NEW.confirmed_at,'created_at',NEW.created_at,'created_by',NEW.created_by,'updated_at',NEW.updated_at,'updated_by',NEW.updated_by,'version',NEW.version,'deleted_at',NEW.deleted_at) ELSE value END)) FROM json_each(feedback_versions_json)) WHERE tenant_id=OLD.tenant_id AND lesson_id=OLD.lesson_id AND student_id=OLD.student_id AND OLD.submission_id IS NULL;
END;
